alias bajl='ns:bajl'
alias nsp='bajl:nsp'
alias md2js='bajl:md2js'
alias zsrc='bajl:zsrc'
alias forget='bajl:forget'
alias lib='bajl:lib'
alias nss='bajl:nss'
alias prudent='bajl:prudent'
alias map='bajl:map '
alias opts='bajl:opts'
alias ns='bajl:ns'
alias tst='bajl:tst'
alias aliases1='bajl:aliases1'
alias fn='bajl:fn'
alias list='bajl:list'
alias txt='bajl:txt'
alias ids='bajl:ids'
alias aliases='bajl:aliases'
alias yml2sh='bajl:yml2sh'
alias fail='bajl:fail'
alias def='bajl:def'
alias self='bajl:self'
alias as-lib='bajl:as-lib'
alias load='bajl:load'
alias listid='bajl:listid'
alias as-cmd='bajl:as-cmd'
alias with-lib='bajl:with-lib'
alias exp='bajl:exp'
alias loop='bajl:loop '
alias fns='bajl:fns'
alias args='bajl:args '
bajl:aliases () 
{ 
    bajl:loop bajl:aliases1 "$@"
}
bajl:aliases1 () 
{ 
    local jq='$ARGS.positional | [.[:$n], .[$n:]] | transpose[] | select(last | test("\($ns):")) | first';
    bajl:nsp ${1:?} || bajl:fail not a ns;
    bajl:self -nr --arg ns $1 --argjson n ${#BASH_ALIASES[@]} --args "${!BASH_ALIASES[@]}" "${BASH_ALIASES[@]}"
}
bajl:args () 
{ 
    mapfile -t;
    ((${#MAPFILE[@]} > 0)) && "${@:-echo}" "${MAPFILE[@]}"
}
bajl:as-cmd () 
{ 
    bajl:as-lib "$@";
    echo 'eval "$@"'
}
bajl:as-lib () 
{ 
    bajl:warn;
    bajl:lib "$@"
}
bajl:def () 
{ 
    bajl:loop bajl:def1 "$@"
}
bajl:def1 () 
{ 
    [[ -v BASH_ALIASES[${1:?}] ]] || bajl:fail $1 not an alias && declare -f ${BASH_ALIASES[$1]}
}
bajl:exp () 
{ 
    bajl:loop bajl:exp1 "$@"
}
bajl:exp1 () 
{ 
    bajl:listid ${1:?} | bajl:args echo export -f
}
bajl:fail () 
{ 
    unset -v fail;
    : "${fail:?${FUNCNAME[1]} $@}"
}
bajl:fn () 
{ 
    bajl:loop bajl:fn1 "$@"
}
bajl:fn1 () 
{ 
    bajl:listid1 ${1:?} | bajl:args declare -f
}
bajl:fns () 
{ 
    bajl:ids "$@" | bajl:args bajl:def
}
bajl:forget () 
{ 
    bajl:loop bajl:forget1 "$@"
}
bajl:forget1 () 
{ 
    . <(${FUNCNAME%%:*}:listid1 ${1:?} | args echo unset -f; nsp $1 && { aliases $1 | args echo unalias; echo unalias $1; })
}
bajl:ids () 
{ 
    bajl:loop bajl:ids1 "$@"
}
bajl:ids1 () 
{ 
    local jq='.[].id';
    eval ${1:?} src | jq "$jq" -r
}
bajl:lib () 
{ 
    bajl:optal;
    bajl:loop bajl:lib1 "$@";
    bajl:def self;
    bajl:exp "$@"
}
bajl:lib1 () 
{ 
    bajl:nsp ${1:?} || bajl:fail not a ns;
    alias $1;
    alias $(aliases $1);
    . <(zsrc $1);
    bajl:fn $1
}
bajl:list () 
{ 
    bajl:loop echo "$@"
}
bajl:listid () 
{ 
    bajl:loop bajl:listid1 "$@"
}
bajl:listid1 () 
{ 
    compgen -c ${1:?}:;
    compgen -c ns:${1:?}
}
bajl:load () 
{ 
    bajl:forget $(nss "$@");
    . <(${FUNCNAME%%:*}:txt "$@")
}
bajl:loop () 
{ 
    local i;
    for i in "${@:2}";
    do
        $1 "$i";
    done
}
bajl:map () 
{ 
    while read; do
        "${@:-echo}" "$REPLY";
    done
}
bajl:md2js () 
{ 
    local -A jq=('header' '[{ m4: { ME: "\($ns)" }}, { id, ns: "ME" }] + input' 'md2js' 'def txt: .c[2] | map(.c // " ") | join("");
def f($b):
  if $b.t == "Header" then ($b | txt) as $h |
    if $h | startswith("id ") then . + [{id: $h[3:]}] else . + [null] end
  elif $b.t == "CodeBlock" and .[-1] then
    .[-1][$b.c[0][1][0] // "txt"] = $b.c[1]
  end;
.blocks | reduce .[] as $b ([]; f($b)) | map(values)');
    pandoc -t json | jq "${jq[md2js]}" | jq "${jq[header]}" -n --arg ns ${1:?}
}
bajl:ns () 
{ 
    (($# == 0)) || bajl:fail too many args;
    compgen -c ns: | cut -d: -f2
}
bajl:nsp () 
{ 
    compgen -c ns:${1:?} > /dev/null
}
bajl:nss () 
{ 
    bajl:loop bajl:nss1 "$@"
}
bajl:nss1 () 
{ 
    local jq='.[].ns // empty';
    yq -oj < ${1:?} | bajl:self -r
}
bajl:optal () 
{ 
    echo shopt -s expand_aliases
}
bajl:opts () 
{ 
    local opt val tmp i;
    args=();
    until [[ $# -eq 0 ]]; do
        case "$1" in 
            --)
                shift;
                break
            ;;
            --*=*)
                opt="${1%%=*}";
                val="${1#*=}";
                opts["${opt:2}"]="$val";
                shift
            ;;
            --*)
                opts["${1:2}"]="1";
                shift
            ;;
            -[0-9]*)
                args+=("$1");
                shift
            ;;
            -)
                args+=("$1");
                shift
            ;;
            -*)
                tmp=${1:1};
                for ((i = 0; i < ${#tmp}; i++ ))
                do
                    opt="${tmp:$i:1}";
                    opts[$opt]=$((opts[$opt] + 1));
                done;
                shift
            ;;
            *)
                args+=("$1");
                shift
            ;;
        esac;
    done;
    cont=("$@")
}
bajl:prudent () 
{ 
    echo set -euo pipefail;
    echo shopt -s inherit_errexit
}
bajl:self () 
{ 
    jq "$jq" "$@"
}
