bajl:tst () 
{ 
    < ${1:?}
}
bajl:txt () 
{ 
    bajl:loop bajl:tst "$@" && bajl:loop bajl:txt1 "$@"
}
bajl:txt1 () 
{ 
    baj:header;
    baj:asjs < ${1:?} | baj:bm4 | baj:dist | baj:emit
}
bajl:warn () 
{ 
    echo \# generated by ${FUNCNAME[1]}, avoid edit
}
bajl:with-lib () 
{ 
    (($#)) || bajl:fail;
    bajl:optal;
    until [[ $# == 0 || $1 == -- ]]; do
        bajl:lib1 $1;
        shift;
    done;
    [[ $1 == -- ]] && shift;
    bajl:def self;
    (($#)) && { 
        f=${BASH_ALIASES[$1]:-$1};
        shift;
        echo $f "${@@Q}"
    }
}
bajl:yml2sh () 
{ 
    bajl:load ${1:?};
    bajl:nss1 $1 | bajl:args bajl:as-cmd
}
bajl:zsrc () 
{ 
    local jq='"\($ns):src () { <<< '\''\(.)'\'' base64 -d | zcat | jq; }"';
    ${1:?}:src | jq -c | gzip | base64 | bajl:self --arg ns $1 -sRr
}
ns:bajl () 
{ 
    bajl:${1:?} "${@:2}"
}
bajl:self () 
{ 
    jq "$jq" "$@"
}
export -f baj:asjs baj:bm4 baj:clean baj:dist baj:emit baj:header baj:init baj:main baj:mk-alias baj:src ns:baj ns:bajl
